function getGenericItemInfo(item: any) {
  const cat = categoryLabels[item.categoryId] || categoryLabels["everyday"];
  return [
    { label: cat[0], value: `ينتمي لفئة ${item.categoryId} 📌` },
    { label: cat[1], value: "معروف عالمياً 🌍" },
    { label: cat[2], value: "متداول ومشهور" },
    { label: cat[3], value: `متعلق بـ ${item.name} ✨` },
    { label: cat[4], value: "له خصائص مميزة" },
    { label: cat[5], value: "مشهور جداً" },
    { label: cat[6], value: "مختلف الفئات" },
    { label: cat[7], value: `يعتبر ${item.name} من العناصر البارزة في مجاله` }
  ];
}

export function getItemCheatSheet(itemName: string) {
  const itemObj = items.find(i => i.name === itemName);
  if (!itemObj) return [];
  
  if (itemData[itemName]) {
    const labels = categoryLabels[itemObj.categoryId] || categoryLabels["everyday"];
    const values = itemData[itemName];
    return labels.map((label, index) => ({
      label,
      value: values[index] || "غير محدد"
    }));
  }

  const catLabels = categoryLabels[itemObj.categoryId] || categoryLabels["everyday"];
  let info = getGenericItemInfo(itemObj);

  if (itemObj.categoryId === 'sports') {
      info[0].value = (itemObj.subcategoryId.includes('players') || itemObj.subcategoryId.includes('athletes')) ? "لاعب رياضي محترف 🏃‍♂️" : "فريق / جهة رياضية 🛡️";
      info[3].value = "الاحتراف الرياضي 🏅";
  } else if (itemObj.categoryId === 'food') {
      info[0].value = "طعام / شراب 🍽️";
      info[2].value = "مكونات غذائية طازجة 🍅";
      info[4].value = "لذيذ وشهي 😋";
      info[6].value = "يعتمد على الوصفة";
  } else if (itemObj.categoryId === 'animals') {
      info[0].value = "كائن حي 🐾";
      info[1].value = "الطبيعة والغابات أو المحيطات 🌳";
      info[6].value = itemObj.subcategoryId === 'pets' ? "نعم، يمكن أن يكون أليفاً 🏡" : "لا، بري 🚫";
  } else if (itemObj.categoryId === 'places') {
      info[0].value = "موقع جغرافي / دولة 🗺️";
      info[6].value = "مكان حيوي 🏙️";
  } else if (itemObj.categoryId === 'cars') {
      info[0].value = "شركة سيارات 🚘";
      info[2].value = "محركات ومركبات ⚙️";
  } else if (itemObj.categoryId === 'tech') {
      info[0].value = "تقنية / تكنولوجيا 💻";
      info[3].value = "تسهيل الحياة والعمل 🚀";
  } else if (itemObj.categoryId === 'games') {
      info[0].value = "لعبة إلكترونية 🎮";
      info[5].value = "المتعة والتحدي 🏆";
  } else if (itemObj.categoryId === 'entertainment') {
      info[0].value = "شخصية ترفيهية 🎭";
      info[2].value = "قدرات خيالية ومميزة ✨";
  } else if (itemObj.categoryId === 'everyday') {
      info[0].value = "استخدام يومي بالمنزل أو العمل 🏠";
  }

  return info.map((fact, i) => ({
      label: catLabels[i],
      value: fact.value
  }));
}
